import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;

public class TestIssueResolved {
    public static void main(String[] args) {
        System.out.println("Issue: CSS attribute selector *=, =, ^=, $= trim whitespace");
        System.out.println("Status: RESOLVED ✓\n");

        // Original issue example
        System.out.println("1. ORIGINAL ISSUE - Contains selector (*=)");
        String html = "<body><article xxx=\"xpaywalled\"></article></body>";
        Document doc = Jsoup.parse(html);

        Elements correct = doc.select("article[xxx*=\"paywalled\"]");
        Elements incorrect = doc.select("article[xxx*=\" paywalled \"]");

        System.out.println("   HTML: <article xxx=\"xpaywalled\"></article>");
        System.out.println("   Selector article[xxx*=\"paywalled\"] matches: " + (correct.size() > 0 ? "✓ YES" : "✗ NO"));
        System.out.println("   Selector article[xxx*=\" paywalled \"] matches: " + (incorrect.size() > 0 ? "✗ YES (WRONG)" : "✓ NO (correct)"));

        // Empty value handling
        System.out.println("\n2. EMPTY ATTRIBUTE VALUES");
        String html2 = "<body><div data=\"\"></div></body>";
        Document doc2 = Jsoup.parse(html2);

        try {
            Elements empty = doc2.select("div[data='']");
            System.out.println("   Selector div[data=''] works: ✓ YES");
            System.out.println("   Matches elements: " + empty.size());
        } catch (Exception ex) {
            System.out.println("   Selector div[data=''] error: ✗ " + ex.getMessage());
        }

        // All affected selectors
        System.out.println("\n3. ALL AFFECTED SELECTORS WITH WHITESPACE");
        String html3 = "<body>" +
                       "<div id='1' attr=\"value\"></div>" +
                       "<div id='2' attr=\" value\"></div>" +
                       "<div id='3' attr=\"value \"></div>" +
                       "<div id='4' attr=\" value \"></div>" +
                       "</body>";
        Document doc3 = Jsoup.parse(html3);

        System.out.println("   = (exact match)");
        Elements eq = doc3.select("div[attr=\"value\"]");
        System.out.println("     [attr=\"value\"] matches id: " + eq.attr("id") + " (expected: 1)");

        Elements eqSpace = doc3.select("div[attr=\" value \"]");
        System.out.println("     [attr=\" value \"] matches id: " + eqSpace.attr("id") + " (expected: 4)");

        System.out.println("   ^= (prefix)");
        Elements prefix = doc3.select("div[attr^=\"value\"]");
        System.out.println("     [attr^=\"value\"] matches id: " + prefix.attr("id") + " (expected: 1)");

        System.out.println("   $= (suffix)");
        Elements suffix = doc3.select("div[attr$=\"value\"]");
        System.out.println("     [attr$=\"value\"] matches id: " + suffix.attr("id") + " (expected: 1)");

        System.out.println("   *= (contains)");
        Elements contains = doc3.select("div[attr*=\"value\"]");
        System.out.println("     [attr*=\"value\"] matches id: " + contains.attr("id") + " (expected: 1)");

        System.out.println("\n✓ Issue resolved: Whitespace is preserved in quoted attribute selectors");
    }
}
EOF
